import{_ as r,C as e,o as s,c as n,j as i,E as d,a as l,a3 as o}from"./chunks/framework.C6R8kWFE.js";const k=JSON.parse(`{"title":"1-hafta (Mentor)","description":"","frontmatter":{"title":"1-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (DevOps)","link":"/mentor/10-sinf-devops/"},"n":1,"bob":"I-bob · Operatsion tizimlar (Linux)","lessons":[{"g":1,"title":"Linux terminal va asosiy buyruqlar: FHS va fayllar tizimi bilan ishlash","lead":"Linux terminali — DevOps muhandisining eng asosiy quroli: serverlarni boshqarish, fayllar daraxti (FHS) bo'ylab chaqqon harakatlanish va tizimni avtomatlashtirishning poydevori.","link":"/mentor/10-sinf-devops/hafta-01/dars-1","slide":"/slaydlar/10-sinf-devops/hafta-01/dars-1.html","test":"/slaydlar/10-sinf-devops/hafta-01/dars-1-test.html"},{"g":2,"title":"Fayl ruxsatlari tizimi va matn tahrirlash vositalari (Nano, Vim)","lead":"Linux xavfsizligining tayanchi bo'lgan ruxsatlar tizimi (ugo/rwx) va server ma'murlari quroli bo'lgan matn muharrirlari (Nano va Vim) sirlari.","link":"/mentor/10-sinf-devops/hafta-01/dars-2","slide":"/slaydlar/10-sinf-devops/hafta-01/dars-2.html","test":"/slaydlar/10-sinf-devops/hafta-01/dars-2-test.html"},{"g":3,"title":"Shell muhiti, tizim o'zgaruvchilari va I/O yo'naltirish (Redirection)","lead":"Linux Shell qudrati: tizim o'zgaruvchilari (PATH, export), .bashrc sozlamalari hamda ma'lumot oqimlari (I/O Redirection va quvurlar) yordamida buyruqlarni zanjirga ulash.","link":"/mentor/10-sinf-devops/hafta-01/dars-3","slide":"/slaydlar/10-sinf-devops/hafta-01/dars-3.html","test":"/slaydlar/10-sinf-devops/hafta-01/dars-3-test.html"}],"test":"/slaydlar/10-sinf-devops/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-devops/hafta-01/index.md","filePath":"mentor/10-sinf-devops/hafta-01/index.md"}`),h={name:"mentor/10-sinf-devops/hafta-01/index.md"},c={class:"blk"},u={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},m={class:"blk"},v={id:"baholash-mezoni",tabindex:"-1"};function g(b,a,y,q,f,p){const t=e("Icon");return s(),n("div",null,[i("div",c,[i("h2",u,[d(t,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>1-haftada Linux operatsion tizimi, terminal asoslari, FHS kataloglar ierarxiyasi, fayl ruxsatlari (chmod/chown), matn muharrirlari (Nano, Vim) hamda Shell muhiti va I/O yo&#39;naltirish mavzulari o&#39;rganildi. Quyidagi topshiriqlar o&#39;tilgan bilimlarni mustahkamlashga qaratilgan.</p><hr><h2 id="_1-dars-vazifasi-linux-fayl-tizimi-va-navigatsiya" tabindex="-1">1-dars vazifasi: Linux fayl tizimi va navigatsiya <a class="header-anchor" href="#_1-dars-vazifasi-linux-fayl-tizimi-va-navigatsiya" aria-label="Permalink to &quot;1-dars vazifasi: Linux fayl tizimi va navigatsiya&quot;">​</a></h2><ol><li>O&#39;z kompyuteringizdagi Linux terminalida (yoki WSL/VirtualBox Ubuntu muhitida) uy katalogingizda <code>devops_lab</code> nomli asosiy papka oching.</li><li><code>mkdir -p</code> yordamida uning ichida <code>projects/backend</code>, <code>projects/frontend</code>, <code>configs</code> va <code>logs</code> papkalarini bir martada yarating.</li><li>Har bir papka ichida bittadan <code>.txt</code> fayl hosil qiling (<code>touch</code> orqali).</li><li><code>projects/backend</code> ichidagi faylni <code>configs</code> papkasi ichiga boshqa nom bilan nusxalang (<code>cp</code>).</li><li><code>logs</code> papkasidagi faylni <code>projects/frontend</code> ga ko&#39;chiring (<code>mv</code>).</li><li><code>history</code> buyrug&#39;i orqali bajargan barcha amallaringiz ro&#39;yxatini daftaringizga qayd eting. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h2 id="_2-dars-vazifasi-ruxsatlar-va-vim-bilan-ishlash" tabindex="-1">2-dars vazifasi: Ruxsatlar va Vim bilan ishlash <a class="header-anchor" href="#_2-dars-vazifasi-ruxsatlar-va-vim-bilan-ishlash" aria-label="Permalink to &quot;2-dars vazifasi: Ruxsatlar va Vim bilan ishlash&quot;">​</a></h2><ol><li><code>devops_lab</code> papkasi ichida <code>start_server.sh</code> va <code>secret.env</code> nomli ikkita fayl yarating.</li><li><code>nano</code> yoki <code>vim</code> yordamida <code>start_server.sh</code> ichiga quyidagi qatorni yozing:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">echo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> &quot;Server 8080-portda muvaffaqiyatli ishga tushdi!&quot;</span></span></code></pre></div></li><li><code>secret.env</code> ichiga esa <code>DB_PASSWORD=&quot;SuperSecret123&quot;</code> qatorini kiriting.</li><li><code>chmod</code> orqali quyidagi qat&#39;iy ruxsatlarni o&#39;rnating: <ul><li><code>start_server.sh</code> fayliga: <code>755</code> (egasi to&#39;liq, guruh va boshqalar faqat o&#39;qish va bajarish).</li><li><code>secret.env</code> fayliga: <code>600</code> (faqat egasi o&#39;qish va yozish, qolgan barcha toifalarga mutlaqo taqiqlash).</li></ul></li><li><code>./start_server.sh</code> buyrug&#39;i bilan skriptingizni ishga tushiring va natijani ko&#39;ring.</li><li><code>ls -l</code> buyrug&#39;i natijasini skrinshot qilib yoki daftaringizga ko&#39;chirib yozing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h2 id="_3-dars-vazifasi-shell-muhiti-aliaslar-va-quvurlar" tabindex="-1">3-dars vazifasi: Shell muhiti, Aliaslar va Quvurlar <a class="header-anchor" href="#_3-dars-vazifasi-shell-muhiti-aliaslar-va-quvurlar" aria-label="Permalink to &quot;3-dars vazifasi: Shell muhiti, Aliaslar va Quvurlar&quot;">​</a></h2><ol><li><code>~/.bashrc</code> faylini <code>vim</code> yoki <code>nano</code> bilan oching.</li><li>Faylning eng oxiriga o&#39;tib, quyidagi sozlamalarni qo&#39;shing: <ul><li><code>export MY_ROLE=&quot;DevOps Engineer&quot;</code></li><li><code>alias dlab=&#39;cd ~/devops_lab &amp;&amp; pwd &amp;&amp; ls -la&#39;</code></li><li><code>alias update_sys=&#39;sudo apt update&#39;</code></li></ul></li><li>Faylni saqlang va <code>source ~/.bashrc</code> buyrug&#39;i orqali o&#39;zgarishlarni qo&#39;llang.</li><li>Terminalda <code>echo $MY_ROLE</code> deb yozib o&#39;zgaruvchi ishlaganini, so&#39;ngra <code>dlab</code> deb yozib yangi alias bir zumda sizni laboratoriya papkangizga olib borganini tekshiring.</li><li><code>/etc</code> katalogidagi barcha fayllar ro&#39;yxatini <code>ls /etc | wc -l</code> quvuri orqali sanang va chiqqan raqamni yozib qo&#39;ying. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><ul><li><strong>Tekshirish mezonlari:</strong><ol><li>O&#39;quvchi FHS va nisbiy/mutlaq yo&#39;llar farqini tushunganmi (<code>cd ..</code>, <code>cd ~</code>, <code>mkdir -p</code>).</li><li>Ruxsatlar to&#39;g&#39;ri berilganmi: <code>deploy.sh</code> da bajarish (<code>x</code>) huquqi bormi, maxfiy fayllar <code>600</code> bilan himoyalanganmi.</li><li>Vim muharririda Normal va Insert rejimlaridan to&#39;g&#39;ri foydalanilganmi.</li><li>Alias va muhit o&#39;zgaruvchilari <code>~/.bashrc</code> faylida xatosiz e&#39;lon qilinganmi.</li></ol></li><li><strong>Tez-tez uchraydigan xatolar:</strong><ul><li>O&#39;zgaruvchi e&#39;lon qilishda tenglik atrofida bo&#39;sh joy qoldirish (<code>NAME = &quot;Ali&quot;</code> deb yozish xatolik beradi).</li><li>Vim&#39;dan chiqishda <code>:wq</code> o&#39;rniga oynani shunchaki yopib yuborish (natijada <code>.swp</code> fayllar hosil bo&#39;ladi).</li><li>Skriptga <code>chmod +x</code> bermasdan <code>./script.sh</code> chaqirish va «Permission denied» xatosiga tushish.</li></ul></li></ul>',13))]),i("div",m,[i("h2",v,[d(t,{name:"list-checks"}),a[3]||(a[3]=l(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Mavzular:</strong></p><ol><li>Linux terminal va asosiy buyruqlar: FHS va fayllar tizimi bilan ishlash</li><li>Fayl ruxsatlari tizimi va matn tahrirlash vositalari (Nano, Vim)</li><li>Shell muhiti, tizim o&#39;zgaruvchilari va I/O yo&#39;naltirish (Redirection)</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Linux va FHS asoslari</strong></td><td>CLI arxitekturasi, FHS kataloglar vazifasi, mutlaq va nisbiy yo&#39;llar, navigatsiya</td><td>30 ball</td></tr><tr><td><strong>Xavfsizlik va Ruxsatlar</strong></td><td>ugo/rwx bitlari, oktal hisoblash (755/644/600), chmod/chown, Vim rejimlari</td><td>30 ball</td></tr><tr><td><strong>Shell va Amaliyot</strong></td><td>Environment o&#39;zgaruvchilari, export, PATH, I/O redirection (&gt;, &gt;&gt;) va quvurlar (</td><td>)</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Linux &amp; FHS (30)</th><th>Ruxsatlar (30)</th><th>Shell &amp; I/O (40)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar dastlab Vim muharririning modal tabiatiga ko&#39;nikishi qiyin kechishi mumkin (ochilishi bilan matn yozmoqchi bo&#39;lishadi). Avval &#39;i&#39; harfini bosish, chiqishda esa &#39;Esc&#39; bosib &#39;:wq&#39; yozish lozimligini bir necha bor birgalikda takrorlang.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> O&#39;z skriptlarini <code>$HOME/bin</code> papkasiga joylab, <code>$PATH</code> ga qo&#39;shish va Linuxda maxsus avtomatik tozalovchi skriptlar yozish topshirig&#39;i berilishi mumkin.</li></ul>',11))])])}const x=r(h,[["render",g]]);export{k as __pageData,x as default};
